import { celsiusToFahrenheit } from "../converter.js";

test("converter module exports a function", () => {
  expect(typeof celsiusToFahrenheit).toBe("function");
});

import { celsiusToFahrenheit } from "../converter.js";

test("0 celsius converts to 32 fahrenheit", () => {
  expect(celsiusToFahrenheit(0)).toBe(32);
});

import { celsiusToFahrenheit } from "../converter.js";

test("100 celsius converts to 212 fahrenheit", () => {
  expect(celsiusToFahrenheit(100)).toBe(212);
});

import { celsiusToFahrenheit } from "../converter.js";

test("-40 celsius converts to -40 fahrenheit", () => {
  expect(celsiusToFahrenheit(-40)).toBe(-40);
});

import { celsiusToFahrenheit } from "../converter.js";

test("37 celsius converts to 98.6 fahrenheit", () => {
  expect(celsiusToFahrenheit(37)).toBeCloseTo(98.6, 5);
});

import { celsiusToFahrenheit } from "../converter.js";

test("converter function handles multiple inputs", () => {
  expect(celsiusToFahrenheit(0)).toBe(32);
  expect(celsiusToFahrenheit(100)).toBe(212);
  expect(celsiusToFahrenheit(-40)).toBe(-40);
});

import { celsiusToFahrenheit } from "../converter.js";

test("converter still works after adding reset", () => {
  expect(celsiusToFahrenheit(25)).toBeCloseTo(77, 5);
});

import { celsiusToFahrenheit } from "../converter.js";

test("converter handles 25 and 100", () => {
  expect(celsiusToFahrenheit(25)).toBeCloseTo(77, 5);
  expect(celsiusToFahrenheit(100)).toBe(212);
});

import { celsiusToFahrenheit } from "../converter.js";

test("converter handles 0 and -40 after reset", () => {
  expect(celsiusToFahrenheit(0)).toBe(32);
  expect(celsiusToFahrenheit(-40)).toBe(-40);
});
